    /// The IT state an instruction sets, where its Execute writes
    /// PSTATE.IT: IT's own, from its condition and mask. Nothing for the
    /// rest, which leave the state to advance.
    pub fn it_state_set(&self) -> Option<ItState> {
        match self {
            Instruction::ItT1 {
                firstcond, mask, ..
            } => Some(ItState::from_bits((*firstcond << 4) | *mask)),
            _ => None,
        }
    }

    /// Whether the word is CONSTRAINED UNPREDICTABLE: it reached a test its
